bad_example:
$numeros = [1, 2, 3];
foreach ($numeros as &$n) { $n *= 2; }
foreach ($numeros as $n) { } // $n aca es alias del ultimo elemento de $numeros
// esto sobreescribe $numeros[2] silenciosamente con el valor de $numeros[1]

good_example:
$numeros = [1, 2, 3];
foreach ($numeros as &$n) { $n *= 2; }
unset($n); // rompe la referencia antes de seguir usando ese nombre
foreach ($numeros as $n) { }

bad_example:
class Contador {
    public static int $valor = 0;
    public function incrementar(): void { $this->valor++; }
}
$a = new Contador(); $a->incrementar();
$b = new Contador(); $b->incrementar();
// Contador::$valor es 2, compartido - $a y $b NO tienen contadores independientes

good_example:
class Contador {
    public int $valor = 0; // propiedad de instancia, no static
    public function incrementar(): void { $this->valor++; }
}
$a = new Contador(); $a->incrementar();
$b = new Contador(); $b->incrementar();
// $a->valor es 1, $b->valor es 1, independientes

